import { describe, it, expect } from 'vitest';
import { DeckInterpreter } from './DeckInterpreter';

describe('DeckInterpreter', () => {
    describe('calculateAspectRatio', () => {
        it('should return correct portrait poker ratio', () => {
            expect(DeckInterpreter.calculateAspectRatio('poker', 'portrait')).toBe(`${2.5 / 3.5}`);
        });

        it('should return correct landscape poker ratio', () => {
            expect(DeckInterpreter.calculateAspectRatio('poker', 'landscape')).toBe(`${3.5 / 2.5}`);
        });

        it('should return correct tarot ratio', () => {
            expect(DeckInterpreter.calculateAspectRatio('tarot', 'portrait')).toBe(`${2.75 / 4.75}`);
        });
    });

    describe('initializeIndices', () => {
        it('should create a shuffled array of indices', () => {
            const manifest = { cardCount: 54, startAtZero: false } as any;
            const indices = DeckInterpreter.initializeIndices(manifest);
            expect(indices).toHaveLength(54);
            expect(indices).toContain(1);
            expect(indices).toContain(54);
            // Non-deterministic check (statistically unlikely to be sorted)
            const sorted = Array.from({ length: 54 }, (_, i) => i + 1);
            expect(indices).not.toEqual(sorted);
        });
    });

    describe('draw', () => {
        it('should draw the first card and return the rest', () => {
            const remaining = [5, 12, 8];
            const result = DeckInterpreter.draw(remaining);
            expect(result.card).toBe(5);
            expect(result.newRemaining).toEqual([12, 8]);
        });

        it('should return null if no cards left', () => {
            const result = DeckInterpreter.draw([]);
            expect(result.card).toBeNull();
            expect(result.newRemaining).toEqual([]);
        });
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handleAddChronicle } from './crossDomainHelpers';
import type { SessionOSStore } from '../store/index';
import { gmToast } from '../../../stores/useToastStore';

vi.mock('../../../stores/useToastStore', () => ({
    gmToast: vi.fn(),
}));

describe('handleAddChronicle (crossDomainHelpers.ts)', () => {
    let mockState: any;
    let mockSet: any;
    let mockGet: any;

    beforeEach(() => {
        vi.clearAllMocks();
        mockState = {
            campaigns: [],
            entities: [],
            atlasMaps: [],
            wikiEntries: [],
            activeCampaignId: null,
            currentView: '',
        };
        mockSet = vi.fn((updateFn: any) => {
            const updates = typeof updateFn === 'function' ? updateFn(mockState) : updateFn;
            mockState = { ...mockState, ...updates };
        });
        mockGet = vi.fn(() => mockState);
    });

    it('adds a new campaign when it does not exist', () => {
        handleAddChronicle(mockSet, mockGet, {
            campaign: { name: 'Test Campaign', system: 'D&D' },
            entities: [{ name: 'Goblin', role: 'monster', hp: 10, maxHp: 10, type: 'npc', status: 'alive' }] as any,
            atlasMaps: [],
            wikiEntries: [],
        });

        expect(mockSet).toHaveBeenCalled();
        expect(mockState.campaigns.length).toBe(1);
        expect(mockState.campaigns[0].name).toBe('Test Campaign');
        expect(mockState.entities.length).toBe(1);
        expect(mockState.entities[0].name).toBe('Goblin');
        expect(mockState.activeCampaignId).toBe(mockState.campaigns[0].id);
        expect(mockState.currentView).toBe('cockpit');
        expect(gmToast).toHaveBeenCalledWith(expect.stringContaining('import├®e avec 1 entit├®s'), 'success');
    });

    it('merges with an existing campaign if name matches', () => {
        mockState.campaigns = [
            { id: 'c-123', name: 'Existing Campaign', system: 'D&D', activeLocationIds: [] }
        ];

        handleAddChronicle(mockSet, mockGet, {
            campaign: { name: 'Existing Campaign', system: 'Custom' },
            entities: [{ name: 'Dragon', type: 'npc', hp: 100, maxHp: 100, status: 'alive' }] as any,
            atlasMaps: [],
            wikiEntries: [],
        });

        expect(mockState.campaigns.length).toBe(1); // Still 1 campaign
        expect(mockState.campaigns[0].system).toBe('Custom'); // Updated system
        expect(mockState.entities.length).toBe(1);
        expect(mockState.entities[0].campaignId).toBe('c-123'); // Maps to existing ID
        expect(gmToast).toHaveBeenCalledWith(expect.stringContaining('fusionn├®e avec "Existing Campaign"'), 'success');
    });

    it('correctly maps entity relations', () => {
        handleAddChronicle(mockSet, mockGet, {
            campaign: { name: 'Relational', system: 'D&D' },
            entities: [
                { name: 'Alice', type: 'npc', hp: 10, maxHp: 10, status: 'alive', relations: [{ targetName: 'Bob', type: 'friend', description: 'friend' }] },
                { name: 'Bob', type: 'npc', hp: 10, maxHp: 10, status: 'alive' }
            ] as any,
            atlasMaps: [],
            wikiEntries: [],
        });

        expect(mockState.entities.length).toBe(2);

        const alice = mockState.entities.find((e: any) => e.name === 'Alice');
        const bob = mockState.entities.find((e: any) => e.name === 'Bob');

        expect(alice).toBeDefined();
        expect(bob).toBeDefined();
        expect(alice.relations.length).toBe(1);
        expect(alice.relations[0].targetId).toBe(bob.id);
        expect(alice.relations[0].type).toBe('friend');
    });
});

import { gmToast } from '../../../stores/useToastStore';
import type { SessionOSStore } from '../store/index';
import type { Campaign, Entity, AtlasMap, WikiEntry, EntityRelation } from '../store/types';

export const handleAddChronicle = (
    set: (partial: Partial<SessionOSStore> | ((state: SessionOSStore) => Partial<SessionOSStore>)) => void,
    get: () => SessionOSStore,
    payload: {
        campaign: Omit<Campaign, 'id'> & { id?: string };
        entities: (Omit<Entity, 'id' | 'campaignId' | 'relations'> & {
            relations?: { targetName: string; type: EntityRelation['type']; description: string }[];
        })[];
        atlasMaps: Omit<AtlasMap, 'id' | 'campaignId'>[];
        wikiEntries: Omit<WikiEntry, 'id' | 'campaignId'>[];
        existingCampaignId?: string;
    }
) => {
    const { campaign, entities, atlasMaps, wikiEntries, existingCampaignId } = payload;
    const state = get();
    const existing = existingCampaignId 
        ? state.campaigns.find(c => c.id === existingCampaignId)
        : state.campaigns.find(c => c.name.toLowerCase() === campaign.name.toLowerCase());

    const campaignId = existing ? existing.id : `c-${Date.now()}`;

    const entityIdMap: Record<string, string> = {};
    const newEntities: Entity[] = entities.map((e) => {
        const id = `e-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
        if (e.name) {
            entityIdMap[e.name] = id;
        }
        return { ...e, id, campaignId, relations: [] } as Entity;
    });

    newEntities.forEach((entity, idx) => {
        const rawRelations = entities[idx].relations ?? [];
        entity.relations = rawRelations.map((r) => ({
            targetId: r.targetName ? (entityIdMap[r.targetName as string] ?? '') : '',
            targetType: 'npc' as const,
            type: r.type as any,
            description: r.description,
        })).filter((r) => r.targetId);
    });

    const newAtlasMaps: AtlasMap[] = atlasMaps.map((m) => ({
        ...m,
        id: `am-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        campaignId,
        linkedEntities: [],
    } as unknown as AtlasMap));

    const newWikiEntries: WikiEntry[] = wikiEntries.map((w) => ({
        ...w,
        id: `we-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        campaignId,
    } as unknown as WikiEntry));

    set((state) => {
        const updatedCampaigns = existing 
            ? state.campaigns.map(c => c.id === existing.id ? { ...c, system: campaign.system || c.system } : c)
            : [...state.campaigns, { ...campaign, id: campaignId, activeLocationIds: [] } as unknown as Campaign];

        return {
            campaigns: updatedCampaigns,
            entities: [...state.entities, ...newEntities],
            atlasMaps: [...state.atlasMaps, ...newAtlasMaps],
            wikiEntries: [...state.wikiEntries, ...newWikiEntries],
            activeCampaignId: campaignId,
            currentView: 'cockpit',
        };
    });

    const msg = existing 
        ? `Chronique fusionn├®e avec "${existing.name}". ${newEntities.length} entit├®s ajout├®es.`
        : `Chronique "${campaign.name}" import├®e avec ${newEntities.length} entit├®s.`;
    gmToast(msg, 'success');
};


export const handleGenerateEntityPortrait = async (
    set: (partial: Partial<SessionOSStore> | ((state: SessionOSStore) => Partial<SessionOSStore>)) => void,
    get: () => SessionOSStore,
    entityId: string, 
    instructions?: string
) => {
    const entity = get().entities.find((e) => e.id === entityId);
    if (!entity) return;
    set({ isGeneratingAIImage: true });
    try {
        const { aiService } = await import('../../ai/AIService');
        const cleanDesc = (entity.description || '').replace(/\n/g, ' ').substring(0, 300);
        const prompt = instructions ?? `A professional fantasy RPG character portrait of ${entity.name}. ${cleanDesc}. High quality digital art, cinematic lighting, 8k.`;
        const mediaId = await aiService.generateImage(prompt);
        get().updateEntity(entityId, { avatar: mediaId });
    } catch (err) {
        console.error('AI Portrait Error:', err);
    } finally {
        set({ isGeneratingAIImage: false });
    }
};

